        const first = {login: 'águero', weight: 2, accountID: 6};
        const second = {login: 'aguero', weight: 2, accountID: 7};
        expect(compareUserInList(first, second)).toBe(-1);
        expect(compareUserInList(second, first)).toBe(1);
    });
});
